mapper.select:
SELECT a.*, c.name AS channel_name, t.title AS topic_name
FROM article a
LEFT JOIN channel c ON a.channel_id = c.id
LEFT JOIN news_topic t ON a.topic_id = t.id

    a.author_id = #{authorId}

        AND a.status = #{status}


        AND a.channel_id = #{channelId}


        AND a.create_time >= #{startDate}


        AND a.create_time <= CONCAT(#{endDate}, ' 23:59:59')


        AND a.title LIKE CONCAT('%', #{keyword}, '%')


ORDER BY a.update_time DESC

SELECT a.*, c.name AS channel_name, t.title AS topic_name, u.nickname AS author_name
FROM article a
LEFT JOIN channel c ON a.channel_id = c.id
LEFT JOIN news_topic t ON a.topic_id = t.id
LEFT JOIN sys_user u ON a.author_id = u.id


        AND a.status = #{status}


        AND a.channel_id = #{channelId}


        AND a.author_id = #{authorId}


        AND a.title LIKE CONCAT('%', #{keyword}, '%')


ORDER BY a.create_time DESC

SELECT a.*, c.name AS channel_name, t.title AS topic_name, u.nickname AS author_name FROM article a LEFT JOIN channel c ON a.channel_id = c.id LEFT JOIN news_topic t ON a.topic_id = t.id LEFT JOIN sys_user u ON a.author_id = u.id WHERE a.status = 2 AND a.topic_id = #{topicId}
AND a.title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY a.is_top DESC, a.publish_time DESC
